{"command":"$utf8NoBom = New-Object System.Text.UTF8Encoding($false)
$files = Get-ChildItem -Path 'Script\Blueprint\Prefabs\Monsters\MainScene' -Recurse -Filter 'BaseMons.lua'
$changed = @()
foreach ($file in $files) {
    $text = [System.IO.File]::ReadAllText($file.FullName, [System.Text.Encoding]::UTF8)
    if ($text -match 'RequestAddTaskProgress\(L_Enum\.AllTask\.KillMonster, 1\)') {
        continue
    }

    $newline = if ($text.Contains("`r`n")) { "`r`n" } else { "`n" }

    if ($text -notmatch 'Script\.Lin\.TaskMgr') {
        $text = [regex]::Replace(
            $text,
            'local BaseMons = \{\}\r?\n',
            "local BaseMons = {}$newline" +
            'local TaskMgr = UGCGameSystem.UGCRequire("Script.Lin.TaskMgr")' + $newline +
            'local L_Enum = UGCGameSystem.UGCRequire("Script.Lin.L_Enum")' + $newline,
            1
        )
    }

    $pattern = '(?s)(function BaseMons:BPDie\(.*?\r?\n    end)(\r?\nend\r?\n\r?\n-- ---)'
    $replacement = '$1' + $newline + $newline + '    TaskMgr:RequestAddTaskProgress(L_Enum.AllTask.KillMonster, 1)' + $newline + '$2'
    $newText = [regex]::Replace($text, $pattern, $replacement, 1)

    if ($newText -eq $text) {
        throw "Could not insert task progress call in $($file.FullName)"
    }

    [System.IO.File]::WriteAllText($file.FullName, $newText, $utf8NoBom)
    $changed += $file.FullName
}
